void DlpAsyncWaiter::CheckScreenShareRestriction(
    ScreenShareAreaPtr area, const ::std::u16string& application_title, bool* out_proceed) {
  base::RunLoop loop;
  proxy_->CheckScreenShareRestriction(std::move(area),std::move(application_title),
      base::BindOnce(
          [](base::RunLoop* loop,
             bool* out_proceed
,
             bool proceed) {*out_proceed = std::move(proceed);
            loop->Quit();
          },
          &loop,
          out_proceed));
  loop.Run();
}

bool DlpAsyncWaiter::CheckScreenShareRestriction(
    ScreenShareAreaPtr area, const ::std::u16string& application_title) {
  bool async_wait_result;
  CheckScreenShareRestriction(std::move(area),std::move(application_title),&async_wait_result);
  return async_wait_result;
}






